{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    min_alloc = [seg['minimum'] for seg in segments]
    capacities = [seg['capacity'] for seg in segments]
    importance = [seg['importance'] for seg in segments]

    total = sum(min_alloc)
    allocations = min_alloc[:]

    while total < budget:
        best_idx = -1
        best_imp = -1
        for i in range(n):
            if allocations[i] < capacities[i]:
                if importance[i] > best_imp:
                    best_imp = importance[i]
                    best_idx = i
        if best_idx == -1:
            break  # cannot allocate more
        allocations[best_idx] += 1
        total += 1

    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': total
    }"
}
